                // v1.1.0 FIX: capture nextPeriod BEFORE the async. The host increments
                // state.currentPeriod synchronously after calculateResults() returns, so reading
                // it inside the timer was two rounds ahead — _updateBriefing() then revealed the
                // WRONG decision panel (round 3's inputs during round 2; no panel during round 3).
                var nextPeriod = (state.currentPeriod || 1) + 1;
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: nextPeriod });
                }, 500);

                // Platform score: same weighted composite as the round 3 totalScore, renormalised
                // over the weight of the components known so far (cv, star and interview)
                var knownWeight2 = 0.20 + 0.20 + 0.35;
                var overallScore2 = Math.round((state.domainState.cvScore * 0.20 + state.domainState.starScore * 0.20 + interviewAvg * 0.35) / knownWeight2);
                overallScore2 = Math.max(0, Math.min(100, overallScore2));
                state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore2 });

                return {
                    period: period,
                    phaseName: phaseName,
                    interviewScore: interviewAvg,
                    interviewResult: interviewResult,
                    roundScore: roundScore,
                    feedback: feedback
                };
            }

            if (period === 3) {
                phaseName = window.mySimulation.t('r3_phase_name');

                var afpScore = d.afpChoice === 'onp' ? 40 : 100;

                var grossSalary = 600;
                var afpRate = 0;
                if (d.afpChoice === 'prima') afpRate = 0.1023;
                else if (d.afpChoice === 'integra') afpRate = 0.1018;
                else if (d.afpChoice === 'habitat') afpRate = 0.0998;
                else if (d.afpChoice === 'profuturo') afpRate = 0.1032;
                else afpRate = 0.13;
                var netSalary = Math.round(grossSalary * (1 - afpRate));

                var conflictMap = { a: 40, b: 20, c: 100 };
                var conflictScore = conflictMap[d.conflict] || 0;
                state.domainState.conflictScore = conflictScore;

                var overtimeMap = { a: 20, b: 40, c: 100 };
                var overtimeScore = overtimeMap[d.overtime] || 0;

                var laborRightsScore = Math.round((afpScore + overtimeScore) / 2);
                state.domainState.laborRightsScore = laborRightsScore;

                roundScore = Math.round(laborRightsScore * 0.6 + conflictScore * 0.4);

                feedback = window.mySimulation.t('r3_feedback_net') + ': PEN ' + netSalary;
                if (d.afpChoice === 'onp') {
                    feedback += '<br>' + window.mySimulation.t('r3_feedback_onp_warning');
                } else {
                    feedback += '<br>' + window.mySimulation.t('r3_feedback_afp_good');
                }

                if (d.conflict === 'c') {
                    feedback += '<br>' + window.mySimulation.t('r3_feedback_conflict_good');
                } else if (d.conflict === 'a') {
                    feedback += '<br>' + window.mySimulation.t('r3_feedback_conflict_passive');
                } else {
                    feedback += '<br>' + window.mySimulation.t('r3_feedback_conflict_avoidant');
                }

                if (d.overtime === 'c') {
                    feedback += '<br>' + window.mySimulation.t('r3_feedback_overtime_good');
                } else if (d.overtime === 'a') {
                    feedback += '<br>' + window.mySimulation.t('r3_feedback_overtime_passive');
                } else {
                    feedback += '<br>' + window.mySimulation.t('r3_feedback_overtime_aggressive');
                }

                if (d.conflict === 'c' && Math.random() < 0.35) {
                    feedback += '<br>✨ ' + window.mySimulation.t('event_valentina_ally');
                    state.domainState.randomEvents.push('valentina_ally');
                }
                if (d.overtime === 'c' && Math.random() < 0.20) {
                    feedback += '<br>✨ ' + window.mySimulation.t('event_new_supervisor');
                    state.domainState.randomEvents.push('new_supervisor');
                }

                var totalScore = Math.round(
                    state.domainState.cvScore * 0.20 +
                    state.domainState.starScore * 0.20 +
                    state.domainState.interviewScore * 0.35 +
                    laborRightsScore * 0.15 +
                    conflictScore * 0.10
                );
                state.domainState.totalScore = totalScore;

                state.domainState.scoreHistory.push(roundScore);
                state.domainState.phaseNames.push(phaseName);
                state.domainState.feedbackHistory.push(feedback);

                // Platform score: round 3 totalScore is already the full weighted composite (0-100)
                var overallScore3 = Math.max(0, Math.min(100, totalScore));
                state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore3 });

                return {
                    period: period,
                    phaseName: phaseName,
                    afpScore: afpScore,
                    conflictScore: conflictScore,
                    overtimeScore: overtimeScore,
                    laborRightsScore: laborRightsScore,
                    netSalary: netSalary,
                    roundScore: roundScore,
                    totalScore: totalScore,
                    feedback: feedback
                };
            }

            return { period: period, roundScore: 0, phaseName: '-', feedback: '' };
        }

