        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastEntry = history[history.length - 1];
            var totalScore = lastEntry.results ? (lastEntry.results.totalScore || 0) : 0;

            var performance = 'Principiante';
            if (totalScore >= 80) performance = 'Excelente';
            else if (totalScore >= 60) performance = 'Bueno';
            else if (totalScore >= 40) performance = 'Regular';

            var insights = [];
            if (history.length >= 1) {
                var r1 = history[0].results || {};
                if ((r1.cvScore || 0) < 80) insights.push(window.mySimulation.t('insight_cv'));
                if ((r1.starScore || 0) < 75) insights.push(window.mySimulation.t('insight_star'));
            }
            if (history.length >= 2) {
                var r2 = history[1].results || {};
                if ((r2.interviewScore || 0) < 60) insights.push(window.mySimulation.t('insight_interview'));
            }
            if (history.length >= 3) {
                var r3 = history[2].results || {};
                if ((r3.laborRightsScore || 0) < 70) insights.push(window.mySimulation.t('insight_labor'));
                if ((r3.conflictScore || 0) < 60) insights.push(window.mySimulation.t('insight_conflict'));
            }

            return {
                totalScore: totalScore,
                performance: performance,
                insights: insights.length > 0 ? insights : [window.mySimulation.t('insight_great')]
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (state.currentPeriod === 1) {
                if (results.cvScore < 60) return window.mySimulation.t('hint_cv_low');
                if (results.prepScore === 0) return window.mySimulation.t('hint_no_prep');
            }
            if (state.currentPeriod === 2) {
                if (results.interviewScore < 50) return window.mySimulation.t('hint_interview_low');
            }
            if (state.currentPeriod === 3) {
                if (results.totalScore >= 80) return window.mySimulation.t('hint_excellent');
                if (results.totalScore < 50) return window.mySimulation.t('hint_needs_work');
            }
            return null;
        }

